'use strict';
(function(){
 const L=AtlasLocations,bar=$('cityBar');let selected=null,searchController=null,weatherController=null,searchToken=0,weatherToken=0,searchResults=[],saved=false;
 const picker=document.createElement('section');picker.className='location-picker';picker.setAttribute('aria-label','Choose your city');
 picker.innerHTML='<form id="locationSearchForm" role="search"><label for="locationQuery">Find your city</label><div class="location-input-row"><input id="locationQuery" type="search" placeholder="City name or US ZIP code" autocomplete="off" maxlength="100" aria-describedby="locationPrivacy locationSearchStatus" aria-controls="locationResults"><button id="locationSearchSubmit" type="submit">Search</button><button id="locationCancel" type="button" hidden>Cancel</button></div></form><p id="locationSearchStatus" class="location-status" role="status" aria-live="polite"></p><div id="locationResults" class="location-results" role="region" aria-label="Matching cities" hidden></div><div class="selected-location"><div><span class="location-kicker">SELECTED LOCATION</span><strong id="selectedLocationName"></strong><span id="locationRememberStatus"></span></div><button id="locationChange" type="button">Change</button><button id="locationClear" type="button">Clear saved city</button></div><p id="locationPrivacy" class="location-privacy">Search sends your query to <a href="https://open-meteo.com/en/terms" target="_blank" rel="noreferrer">Open-Meteo</a>. Selected coordinates are used to load weather, including when you return. Your choice is saved only in this browser. No GPS is used. ZIP codes select an associated city, not an exact address.</p>';
 const samples=document.createElement('details');samples.className='sample-cities';const summary=document.createElement('summary');summary.textContent='Or explore a sample city';samples.append(summary);bar.before(picker);picker.append(samples);samples.append(bar);bar.querySelector('label').textContent='Sample city';
 const input=$('locationQuery'),status=$('locationSearchStatus'),resultBox=$('locationResults');
 function storage(){try{return localStorage}catch{return null}}
 function writeChoice(record){const s=storage();saved=!!s&&L.save(s,record);try{s?.removeItem('enso-workspace-location')}catch{}}
 function selectedUI(note){const loc=AtlasWorkspace.location();$('selectedLocationName').textContent=selected?.label||loc[0];$('locationRememberStatus').textContent=note||(saved?'Saved in this browser · restored when you return':selected?'For this visit · browser storage is unavailable':'Sample location · search to choose your city');$('locationClear').hidden=!selected&&!saved;}
 function cancelSearch(message=''){++searchToken;searchController?.abort();searchController=null;searchResults=[];resultBox.replaceChildren();resultBox.hidden=true;$('locationCancel').hidden=true;$('locationSearchSubmit').disabled=false;status.textContent=message;}
 function cancelWeather(){++weatherToken;weatherController?.abort();weatherController=null;customGfsState.loading=false;}
 function showResults(records){searchResults=records;resultBox.replaceChildren();resultBox.hidden=!records.length;for(const record of records){const button=document.createElement('button');button.type='button';button.className='location-result';const title=document.createElement('strong'),detail=document.createElement('span');title.textContent=record.name;detail.textContent=[record.admin2,record.admin1,record.country,record.zip?'US ZIP '+record.zip:null].filter(Boolean).join(' · ')||record.latitude.toFixed(3)+'°, '+record.longitude.toFixed(3)+'°';button.append(title,detail);button.setAttribute('aria-label',record.label);button.onclick=()=>choose(record);resultBox.append(button)}status.textContent=records.length?records.length+' matching '+(records.length===1?'city':'places')+'. Choose the right location below.':'No matching city found. Try a nearby city, add a state or country, or check the US ZIP code.';}
 $('locationSearchForm').onsubmit=async e=>{e.preventDefault();cancelSearch();const q=L.query(input.value);if(q.error){status.textContent=q.error;input.focus();return}const token=++searchToken;searchController=new AbortController();const controller=searchController,timeout=setTimeout(()=>controller.abort(),12000);status.textContent='Searching cities…';$('locationCancel').hidden=false;try{const response=await fetch(L.searchURL(q),{signal:searchController.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('Search unavailable');const data=await response.json();if(token!==searchToken)return;showResults(L.results(data,q));}catch{if(token===searchToken)status.textContent='City search is temporarily unavailable. Try again or explore a sample city.';}finally{clearTimeout(timeout);if(token===searchToken){searchController=null;$('locationCancel').hidden=true;}}};
 input.addEventListener('input',()=>cancelSearch());input.addEventListener('keydown',e=>{if(e.key==='Escape'){cancelSearch('Search closed. Your selected city is unchanged.');e.preventDefault()}if(e.key==='ArrowDown'&&!resultBox.hidden){resultBox.querySelector('button')?.focus();e.preventDefault()}});
 resultBox.addEventListener('keydown',e=>{const buttons=[...resultBox.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}if(e.key==='Escape'){cancelSearch('Search closed. Your selected city is unchanged.');input.focus()}});
 $('locationCancel').onclick=()=>{cancelSearch('Search canceled. Your selected city is unchanged.');input.focus()};
 $('locationChange').onclick=()=>{input.value='';cancelSearch();input.focus()};
 function cachedForecast(record){try{const raw=storage()?.getItem(L.forecastKey);if(!raw||raw.length>150000)return null;const c=JSON.parse(raw),age=Date.now()-Date.parse(c.fetched);return c.version===1&&c.identity===L.identity(record)&&age>=0&&age<7*86400000&&L.validForecast(c.data,record)?c:null}catch{return null}}
 async function fetchWeather(force=false){if(!selected||city<presetCityCount)return;cancelWeather();const record=selected,token=weatherToken;const cached=cachedForecast(record);if(cached&&!force){forecasts[presetCityCount]=cached.data;customGfsState={loading:false,error:false,fetched:cached.fetched,snapshot:Date.now()-Date.parse(cached.fetched)>=3600000};AtlasWorkspace.update();if(!customGfsState.snapshot)return;}weatherController=new AbortController();const controller=weatherController,timeout=setTimeout(()=>controller.abort(),20000);customGfsState={...customGfsState,loading:true,error:false};AtlasWorkspace.update();try{const response=await fetch(L.forecastURL(record),{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('GFS unavailable');const data=await response.json();if(!L.validForecast(data,record))throw Error('Invalid GFS');if(token!==weatherToken||!selected||L.identity(selected)!==L.identity(record))return;forecasts[presetCityCount]=data;customGfsState={loading:false,error:false,fetched:new Date().toISOString(),snapshot:false};try{storage()?.setItem(L.forecastKey,JSON.stringify({version:1,identity:L.identity(record),fetched:customGfsState.fetched,data}))}catch{};}catch{if(token===weatherToken)customGfsState={...customGfsState,loading:false,error:true,snapshot:!!forecasts[presetCityCount]};}finally{clearTimeout(timeout);if(token===weatherToken){weatherController=null;AtlasWorkspace.update();}}}
 function choose(record,{remember=true,focus=true}={}){if(!L.validLocation(record))return;cancelSearch();cancelWeather();selected=record;if(remember)writeChoice(record);AtlasWorkspace.select(record);selectedUI();input.value='';status.textContent=record.zip?'Selected '+record.name+' for ZIP '+record.zip+'. Weather uses city-level coordinates.':'Selected '+record.label+'.';if(focus)$('locationChange').focus();fetchWeather();}
 $('locationClear').onclick=()=>{cancelSearch();cancelWeather();selected=null;saved=false;let cleared=true;try{const s=storage();if(!s)cleared=false;else for(const key of [L.key,L.forecastKey,'enso-workspace-location'])s.removeItem(key)}catch{cleared=false}AtlasWorkspace.reset();selectedUI(cleared?'Saved city cleared · showing sample San Francisco':'City cleared for this visit · browser storage could not be changed');status.textContent='Search for a city whenever you’re ready.';input.value='';input.focus();};
 window.AtlasLocationSearch={hasSelection:()=>!!selected,resume:()=>fetchWeather(false),refresh:()=>fetchWeather(true),preset(name){cancelWeather();const c=cities.find(c=>c[0]===name),p=c||cfs?.sampledLocations.find(c=>c.name===name)?.requestedCoordinate;if(!p)return;const record={version:1,name,label:name,latitude:c?c[1]:p[0],longitude:c?c[2]:p[1],source:'preset'};selected=record;writeChoice(record);selectedUI();cancelSearch();},coordinates(point){choose({version:1,name:'Custom coordinates',label:point.map(n=>n.toFixed(2)+'°').join(', '),latitude:point[0],longitude:point[1],source:'coordinates'},{focus:false});}};
 // Overlay always marks the requested city, including outside a regional product footprint.
 const originalDraw=drawNow;drawNow=function(){originalDraw();if(!selected||!W)return;const p=project(selected.longitude,selected.latitude);if(p[2]<=.02)return;ctx.save();ctx.strokeStyle='#f8d680';ctx.fillStyle='#f8d680';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p[0],p[1],10,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(p[0],p[1],3,0,Math.PI*2);ctx.fill();ctx.font='600 13px "DM Sans", sans-serif';const name=selected.name,metrics=ctx.measureText(name),width=metrics.width||name.length*8,x=Math.max(8,Math.min(W-width-12,p[0]+15)),y=Math.max(20,Math.min(H-15,p[1]-14));ctx.fillStyle='#07151f';ctx.fillRect(x-5,y-15,width+10,22);ctx.fillStyle='#fff2cd';ctx.fillText(name,x,y);ctx.restore();};
 const stored=L.read(storage());if(stored){saved=true;choose(stored,{remember:false,focus:false})}else{try{storage()?.removeItem(L.key)}catch{}selectedUI();}
 const footer=document.createElement('span');footer.innerHTML='City search: <a href="https://open-meteo.com/" target="_blank" rel="noreferrer">Open-Meteo</a> / <a href="https://www.geonames.org/" target="_blank" rel="noreferrer">GeoNames</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>';document.querySelector('footer').append(footer);
})();
